//! Content and Fidelity variants against `@material/material-color-utilities` 0.4.0.
//!
//! `fixtures/mcu-fidelity.json` is generated by `m3/packages/m3-theme/scripts/mcu-fidelity-fixture.ts`
//! (`bun run fixture:mcu-fidelity`): every role, both modes, contrast -1, 0, 0.5 and 1, for the
//! creator-site and pet seeds plus seeds on the dislike (dark yellow-green) branch.

#![cfg(feature = "std")]

use aphrody_m3_tokens::scheme::{DynamicScheme, Role, Variant};
use serde_json::Value;

fn u32_of(value: &Value) -> u32 {
    u32::try_from(value.as_u64().expect("integer")).expect("u32")
}

#[test]
fn content_and_fidelity_match_mcu_for_every_role() {
    let fixture: Value =
        serde_json::from_str(include_str!("fixtures/mcu-fidelity.json")).expect("valid fixture");
    let schemes = fixture["schemes"].as_array().unwrap();
    assert_eq!(schemes.len(), 144);
    for s in schemes {
        let variant = Variant::from_name(s["variant"].as_str().unwrap()).unwrap();
        let dark = s["dark"].as_bool().unwrap();
        let contrast = s["contrast"].as_f64().unwrap();
        let seed = u32_of(&s["seed"]);
        let scheme = DynamicScheme::from_argb(seed, variant, dark, contrast);
        let roles = s["roles"].as_object().unwrap();
        assert_eq!(roles.len(), 54);
        for (name, want) in roles {
            let role = Role::from_name(name).unwrap_or_else(|| panic!("unknown role {name}"));
            assert_eq!(
                scheme.argb(role),
                u32_of(want),
                "{seed:#010x} {} dark={dark} contrast={contrast} {name}",
                variant.name()
            );
        }
    }
}
